const bounded=(promise,ms,label)=>Promise.race([promise,sleep(ms).then(()=>({timeout:label}))]);

async function peerState(instance){const result=await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionState.ts")]).then(async([{mockAdapter},{connectedStateFor}])=>{const s=await mockAdapter.getSnapshot();const st=connectedStateFor(mockAdapter);const r=s.resolution;done({role:s.session.role,connectionState:s.connectionState,mode:s.sessionMode,currentActorId:s.scene.currentActorId,cursor:st.replica?.cursor??st.ledger?.cursor??null,pendingRemote:Boolean(st.pendingRemoteAction),compatibilityMessage:s.session.compatibilityMessage,activeCharacterId:s.activeCharacter.id,slots:(s.scene.spellcastingByActor?.[s.activeCharacter.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max})),announcement:document.querySelector(".session-resolution-announcement")?.textContent??"",resolution:r?{id:r.id,stage:r.stage,actorId:r.actorId,actionName:r.actionName,targetIds:r.targetIds,dice:r.authoritativeDice,compact:r.compact,finalOutcome:r.finalOutcome,attackOutcome:r.attackOutcome,attackTotal:r.attackTotal,rollTotal:r.rollTotal,critical:r.critical,canAdvance:r.canAdvance,stateChanges:r.stateChanges,damageComponents:(r.damageComponents??[]).length,checkTarget:r.checkTarget,checkOutcome:r.checkOutcome,saves:(r.saveResults??[]).map((x)=>({targetId:x.targetId,targetName:x.targetName,total:x.total,dc:x.dc,outcome:x.outcome}))}:null,items:s.activeCharacter.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped})),inventory:(()=>{const inv=s.sessionCharacterInventories?.[s.activeCharacter.id];return inv?{revision:inv.revision,goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity}))}:null;})(),activity:s.activity.slice(0,60).map((e)=>({id:e.id,actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges,detail:e.detail})),entities:s.scene.entities.map((e)=>({id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,kind:e.kind,initiative:e.initiative??null,side:e.side,status:[...(e.status??[])]})),resources:(s.activeCharacter.resources??[]).map((x)=>({id:x.id,label:x.label,current:x.current,max:x.max})),hasCanvas:Boolean(document.querySelector("canvas"))});}).catch((error)=>done({error:String(error?.stack??error)}));});assert.ok(!result.error,result.error);return result;}
async function refreshShell(instance){await instance.browser.executeAsync((done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{await publishConnectedSnapshot(mockAdapter);done({ok:true});}).catch((error)=>done({error:String(error?.stack??error)}));});}
async function actions(instance,actorId){return instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();done((s.scene.actionsByActor[actorId]??[]).map((a)=>({id:a.id,name:a.name,available:a.available,disabledReason:a.disabledReason,target:a.target,eligibleTargetIds:a.eligibleTargetIds,resolutionKind:a.resolutionKind,economy:a.economy,spellId:a.spellCast?.spellId??null,readyActionRole:a.readyActionRole??null,maxTargets:a.maxTargets??null})));}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);}
async function findAction(instance,actorId,predicate,label){const list=await actions(instance,actorId);assert.ok(!list.error,list.error);const found=list.find(predicate);assert.ok(found,`${instance.label}: action ${label} not projected for ${actorId}; have ${list.map((a)=>a.name).join("|")}`);return found;}
const HOST_LEDGER_DIAG='const [{connectedStateFor},{decodeConnectedWireMessage}]=await Promise.all([import("/src/app/connectedSessionState.ts"),import("/src/app/connectedSessionWire.ts")]);const st=connectedStateFor(mockAdapter);if(!st.ledger)return null;const c=st.ledger.cursor;const events=st.ledger.eventsAfter(Math.max(0,c-3));const decoded=events.map((e)=>{const r=decodeConnectedWireMessage(JSON.stringify({type:"event-batch",sessionId:st.ledger.sessionId,afterCursor:e.sequence-1,events:[e]}));return {sequence:e.sequence,kind:e.payload.kind,decode:r.status==="ok"?"ok":r.error};});return {cursor:c,decoded,events};';
async function hostCall(host,body,args){const result=await host.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,result.error);return result.out;}
const seenResolutionIds=new Set();
// Walks the authoritative Initiative to the actor's next fresh turn. If the actor is already current its turn economy may be spent, so the Host ends that turn first and cycles the order once.
async function peerCall(instance,body,args){const result=await instance.browser.executeAsync(new Function("args","done",`Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const out=await (async()=>{${body}})();await publishConnectedSnapshot(mockAdapter);done({ok:true,out});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));`),args??{});assert.equal(result.ok,true,`${instance.label}: ${result.error}`);return result.out;}
// A created Cleric holds mace + shield; stowing the shield through the production inventory API frees the hand that somatic-only spells (Sacred Flame, Guiding Bolt, Cure Wounds) need.
async function stowShield(instance){return peerCall(instance,`const s=await mockAdapter.getSnapshot();const shield=s.activeCharacter.items.find((i)=>i.definitionId==="dnd.srd521.item.shield"&&i.equipped);if(!shield)return {stowed:false,items:s.activeCharacter.items.map((i)=>i.name+":"+(i.equipped?"E":"-")+(i.wielded?"W":"-"))};const after=await mockAdapter.toggleItemEquipped(shield.id);return {stowed:true,wielded:after.activeCharacter.items.filter((i)=>i.wielded).map((i)=>i.name+":"+i.wieldSlot)};`);}
async function paritySnapshot(instance,actorId){const result=await instance.browser.executeAsync((actorId,done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();const e=s.scene.entities.find((x)=>x.id===actorId);const norm=(a)=>({id:a.id,name:a.name,category:a.category,economy:a.economy,target:a.target,available:a.available,resolutionKind:a.resolutionKind,eligibleTargetIds:[...(a.eligibleTargetIds??[])].sort(),maxTargets:a.maxTargets??null,spellId:a.spellCast?.spellId??null});const inv=s.sessionCharacterInventories?.[actorId];done({roster:s.scene.entities.map((x)=>({id:x.id,name:x.name,side:x.side,kind:x.kind})).sort((a,b)=>a.id<b.id?-1:1),actor:e?{id:e.id,name:e.name,hp:e.hp,maxHp:e.maxHp,tempHp:e.tempHp,ac:e.ac,status:[...e.status].sort(),initiative:e.initiative}:null,economy:s.scene.economyByActor[actorId]??null,currentActorId:s.scene.currentActorId,mode:s.sessionMode,actions:(s.scene.actionsByActor[actorId]??[]).map(norm).sort((a,b)=>a.id<b.id?-1:1),inventory:inv?{goldGp:inv.goldGp,items:inv.items.map((i)=>({id:i.id,definitionId:i.definitionId,name:i.name,quantity:i.quantity,equipped:i.equipped,wielded:i.wielded??false,wieldSlot:i.wieldSlot??null})).sort((a,b)=>a.id<b.id?-1:1)}:null});}).catch((error)=>done({error:String(error?.stack??error)}));},actorId);assert.ok(!result.error,result.error);return result;}
function actionParityDiff(hostActions,clientActions,{compareAvailability=true}={}){const byId=new Map(clientActions.map((a)=>[a.id,a]));const diffs=[];for(const h of hostActions){const c=byId.get(h.id);if(!c){diffs.push(`missing on client: ${h.id}`);continue;}for(const key of ["name","category","economy","target","resolutionKind","maxTargets","spellId",...(compareAvailability?["available"]:[])]){if(JSON.stringify(h[key])!==JSON.stringify(c[key]))diffs.push(`${h.id}.${key}: host=${JSON.stringify(h[key])} client=${JSON.stringify(c[key])}`);}if(JSON.stringify(h.eligibleTargetIds)!==JSON.stringify(c.eligibleTargetIds))diffs.push(`${h.id}.eligibleTargetIds: host=${JSON.stringify(h.eligibleTargetIds)} client=${JSON.stringify(c.eligibleTargetIds)}`);}for(const c of clientActions)if(!hostActions.some((h)=>h.id===c.id))diffs.push(`missing on host: ${c.id}`);return diffs;}
async function expectUiParity(host,client,actorId,label){const h=await paritySnapshot(host,actorId);const c=await paritySnapshot(client,actorId);assert.deepEqual(c.roster,h.roster,`${label}: roster diverges`);assert.deepEqual(c.actor,h.actor,`${label}: Actor projection diverges`);assert.deepEqual(c.economy,h.economy,`${label}: turn economy diverges`);assert.equal(c.currentActorId,h.currentActorId,`${label}: current Actor diverges`);const ownTurn=h.currentActorId===actorId;const diffs=actionParityDiff(h.actions,c.actions,{compareAvailability:ownTurn});assert.deepEqual(diffs,[],`${label}: action bar diverges: ${diffs.slice(0,12).join(" | ")}`);if(h.inventory&&c.inventory){assert.equal(c.inventory.goldGp,h.inventory.goldGp,`${label}: GP diverges`);assert.deepEqual(c.inventory.items,h.inventory.items,`${label}: inventory diverges`);}return {actions:h.actions.length,items:h.inventory?.items.length??null,goldGp:h.inventory?.goldGp??null,roster:h.roster.length,availabilityCompared:ownTurn,offTurnAvailability:ownTurn?null:{host:h.actions.filter((a)=>a.available).length,client:c.actions.filter((a)=>a.available).length}};}
async function walkToActor(host,actorId,{fresh=true}={}){const before=await peerState(host);if(before.mode!=="initiative")await hostCall(host,`await mockAdapter.startInitiative();`);else if(fresh&&before.currentActorId===actorId)await hostCall(host,`await mockAdapter.endTurn();`);for(let step=0;step<16;step+=1){const s=await peerState(host);if(s.currentActorId===actorId)return s;await hostCall(host,`await mockAdapter.endTurn();`);}const s=await peerState(host);throw new Error(`Host could not walk the initiative order to ${actorId}; current=${s.currentActorId} entities=${s.entities.map((e)=>e.id).join(",")}`);}
async function hostAdvanceToComplete(host,resolutionId){let last=null;for(let step=0;step<14;step+=1){last=await peerState(host);if(!last.resolution||last.resolution.id!==resolutionId)break;if(last.resolution.stage==="complete")return last;if(!last.resolution.canAdvance){await sleep(300);continue;}await hostCall(host,`await mockAdapter.advanceResolution();`);}last=await peerState(host);return last;}
async function clientAct(client,actionId,targetIds){return client.browser.executeAsync((actionId,targetIds,done)=>{Promise.all([import("/src/app/mockAdapter.ts"),import("/src/app/connectedSessionRuntimeAdapter.ts")]).then(async([{mockAdapter},{publishConnectedSnapshot}])=>{try{const s=await mockAdapter.resolveAction(actionId,targetIds);await publishConnectedSnapshot(mockAdapter);done({ok:true,resolutionId:s.resolution?.id??null,stage:s.resolution?.stage??null,compatibilityMessage:s.session.compatibilityMessage});}catch(error){done({ok:false,error:String(error instanceof Error?error.message:error)});}}).catch((error)=>done({ok:false,error:String(error?.stack??error)}));},actionId,targetIds);}
async function waitHostResolutionFor(host,actorId,timeout=20_000){let last=null;await host.browser.waitUntil(async()=>{last=await peerState(host);return Boolean(last.resolution&&last.resolution.actorId===actorId&&!seenResolutionIds.has(last.resolution.id));},{timeout,interval:200,timeoutMsg:`Host did not start a new Resolution for ${actorId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});seenResolutionIds.add(last.resolution.id);return last;}
async function waitActivityEntry(instance,resolutionId,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await peerState(instance);return last.activity.some((e)=>e.id===resolutionId);},{timeout,interval:200,timeoutMsg:`${instance.label} did not record ${resolutionId}; activity=${JSON.stringify(last?.activity?.map((e)=>e.id))} msg=${last?.compatibilityMessage}`});return last;}
async function openActivity(instance){const open=await instance.browser.$("aside.session-activity-pane");if(await open.isExisting())return;await click(instance.browser,exactButton("기록"),`${instance.label} 기록 패널`);await instance.browser.$("aside.session-activity-pane").waitForExist({timeout:10_000});}
async function closeActivity(instance){await instance.browser.keys("Escape");await sleep(200);}
async function renderedActivityText(instance){await openActivity(instance);const text=await instance.browser.$("aside.session-activity-pane").getText().catch(async()=>bodyText(instance));return text;}
function d20FaceOf(state,resolutionId){const entry=state.activity.find((e)=>e.id===resolutionId);const detail=(entry?.detail??[]).join("\n");const match=detail.match(/selected d20 (\d+)/);if(match)return Number(match[1]);const dice=state.resolution&&state.resolution.id===resolutionId?state.resolution.dice:[];return dice.length?dice[0]:null;}
function assertQueuedD20(state,resolutionId,face,label){const seen=d20FaceOf(state,resolutionId);assert.equal(seen,face,`${label}: authoritative d20 must be the queued ${face}; Host committed ${seen} (dice=${JSON.stringify(state.resolution?.dice)})`);}
function entity(state,id){return state.entities.find((e)=>e.id===id);}
const terminalView=(r)=>r?{id:r.id,stage:r.stage,actionName:r.actionName,actorId:r.actorId,targetIds:r.targetIds,attackOutcome:r.attackOutcome??null,attackTotal:r.attackTotal??null,rollTotal:r.rollTotal??null,finalOutcome:r.finalOutcome??null,compact:r.compact??null,critical:r.critical??null,checkOutcome:r.checkOutcome??null}:null;
async function waitClientTerminal(client,resolutionId,timeout=30_000){let last=null,announcement="";await client.browser.waitUntil(async()=>{last=await peerState(client);if(last.announcement&&last.announcement.length>announcement.length)announcement=last.announcement;const applied=last.activity.some((e)=>e.id===resolutionId);if(!applied)return false;const r=last.resolution;if(r&&r.id===resolutionId)return r.stage==="complete";return true;},{timeout,interval:200,timeoutMsg:`${client.label} did not reach the terminal presentation of ${resolutionId}; last=${JSON.stringify(last?.resolution)} msg=${last?.compatibilityMessage}`});return{state:last,announcement};}
async function expectConverged(peers,resolutionId,label){const host=await waitActivityEntry(peers[0],resolutionId);const hostEntry=host.activity.find((e)=>e.id===resolutionId);const states=[[peers[0].label,host]];const views=[];const announcements={};const clientEntries=[];for(const p of peers.slice(1)){const {state,announcement}=await waitClientTerminal(p,resolutionId);states.push([p.label,state]);announcements[p.label]=announcement;const e=state.activity.find((x)=>x.id===resolutionId);assert.ok(e,`${label}: ${p.label} has no committed entry`);clientEntries.push([p.label,{title:e.title,summary:e.summary,stateChanges:e.stateChanges}]);for(const he of host.entities){const pe=entity(state,he.id);if(pe)assert.equal(pe.hp,he.hp,`${label}: ${p.label} HP for ${he.name} diverges (${pe.hp} vs Host ${he.hp})`);}if(state.resolution&&state.resolution.id===resolutionId)views.push([p.label,terminalView(state.resolution)]);}for(const [name,entry] of clientEntries.slice(1))assert.deepEqual(entry,clientEntries[0][1],`${label}: ${name} committed entry diverges from ${clientEntries[0][0]}`);if(views.length>=2){for(const [name,view] of views.slice(1))assert.deepEqual(view,views[0][1],`${label}: ${name} terminal resolution view diverges from ${views[0][0]}`);}assert.ok(hostEntry,`${label}: Host has no committed entry`);states.announcements=announcements;states.views=views;return states;}
async function evidenceAll(peers,suffix){for(const p of peers)await bounded(saveEvidence(p,suffix).catch(()=>undefined),15_000,"evidence");}

async function hostResolutionDetail(host){return hostCall(host,`const s=await mockAdapter.getSnapshot();const r=s.resolution;return r?{id:r.id,stage:r.stage,actionId:r.actionId,attackTotal:r.attackTotal??null,naturalD20:r.naturalD20??null,attackOutcome:r.attackOutcome??null,contributions:r.rollModifierContributions??[],detail:r.detail,provenance:r.provenance,interrupt:r.interrupt?{id:r.interrupt.id}:null}:null;`);}

async function stateOf(instance){const result=await instance.browser.executeAsync((done)=>{import("/src/app/mockAdapter.ts").then(async({mockAdapter})=>{const s=await mockAdapter.getSnapshot();done({role:s.session.role,lifecycle:s.session.lifecycle??null,connectionState:s.connectionState,mode:s.sessionMode,round:s.scene.round??null,currentActorId:s.scene.currentActorId,activeCharacterId:s.activeCharacter.id,activeCharacterName:s.activeCharacter.name,participants:s.session.participants.map((p)=>({id:p.id,characterName:p.characterName,state:p.state})),slots:(s.scene.spellcastingByActor?.[s.activeCharacter.id]?.slots??[]).map((l)=>({level:l.level,current:l.current,max:l.max})),entities:s.scene.entities.map((e)=>({id:e.id,name:e.name,kind:e.kind,side:e.side,hp:e.hp,maxHp:e.maxHp,ac:e.ac,initiative:e.initiative??null,status:[...(e.status??[])].sort(),movement:e.movementDeclaration?.kind??s.scene.movementDeclarations?.[e.id]?.kind??null})).sort((a,b)=>a.id<b.id?-1:1),activity:s.activity.slice(0,80).map((e)=>({id:e.id,actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges})),resolution:s.resolution?{id:s.resolution.id,stage:s.resolution.stage,actorId:s.resolution.actorId,actionName:s.resolution.actionName,canAdvance:s.resolution.canAdvance}:null});}).catch((error)=>done({error:String(error?.stack??error)}));});assert.ok(!result.error,`${instance.label}: ${result.error}`);return result;}
async function waitState(instance,predicate,description,timeout=20_000){let last=null;await instance.browser.waitUntil(async()=>{last=await stateOf(instance);return predicate(last);},{timeout,interval:200,timeoutMsg:`${instance.label} did not reach ${description}; last=${JSON.stringify({role:last?.role,connectionState:last?.connectionState,mode:last?.mode,current:last?.currentActorId,entities:last?.entities?.map((e)=>`${e.name}:${e.hp}`),activity:last?.activity?.slice(0,4).map((e)=>e.title)})}`});return last;}
function publicEntities(state){return state.entities.map((e)=>({id:e.id,name:e.name,kind:e.kind,side:e.side,hp:e.hp,maxHp:e.maxHp,initiative:e.initiative,status:e.status}));}
async function expectSceneParity(peers,label){const host=await stateOf(peers[0]);const expected=publicEntities(host);for(const p of peers.slice(1)){const s=await waitState(p,(x)=>JSON.stringify(publicEntities(x))===JSON.stringify(expected),`${label}: scene parity with the Host`);assert.equal(s.mode,host.mode,`${label}: ${p.label} mode diverges`);assert.equal(s.currentActorId,host.currentActorId,`${label}: ${p.label} current actor diverges`);}return host;}
async function openUtility(instance,label){const pressed=await instance.browser.$(`//button[normalize-space(.)=${JSON.stringify(label)} and contains(@class,'active')]`);if(await pressed.isExisting())return;await click(instance.browser,exactButton(label),`${instance.label} ${label}`);await sleep(300);}
async function hostEncounterPane(host){await openUtility(host,"인카운터");const pane="//aside[@aria-label='DM Encounter 도구']";await host.browser.$(pane).waitForDisplayed({timeout:10_000,timeoutMsg:"DM Encounter 도구 pane did not open"});return pane;}
async function addSrdMonsterViaUi(host,query,namePrefix){const pane=await hostEncounterPane(host);await replaceValue(host.browser,`${pane}//input[@aria-label='SRD 몬스터 검색']`,query,"SRD 몬스터 검색");const result=`${pane}//div[contains(@class,'session-dm-monster-results')]//button[.//strong[starts-with(normalize-space(.),${JSON.stringify(namePrefix)})]]`;await click(host.browser,result,`SRD 몬스터 ${namePrefix}`);const state=await waitState(host,(s)=>s.entities.some((e)=>e.kind!=="character"&&e.name.startsWith(namePrefix)),`${namePrefix} in the Host scene`);return state.entities.find((e)=>e.kind!=="character"&&e.name.startsWith(namePrefix));}
async function newActivitySince(instance,knownIds,minimum,timeout=25_000){let fresh=[];await instance.browser.waitUntil(async()=>{const s=await stateOf(instance);fresh=s.activity.filter((e)=>!knownIds.has(e.id));return fresh.length>=minimum&&(!s.resolution||s.resolution.stage==="complete");},{timeout,interval:250,timeoutMsg:`${instance.label} did not record ${minimum} new activity entries; fresh=${JSON.stringify(fresh.map((e)=>e.title))}`});return fresh;}
async function waitActivityIds(instance,ids,timeout=25_000){let missing=ids;await instance.browser.waitUntil(async()=>{const s=await stateOf(instance);const have=new Set(s.activity.map((e)=>e.id));missing=ids.filter((id)=>!have.has(id));return missing.length===0;},{timeout,interval:250,timeoutMsg:`${instance.label} is missing activity ${JSON.stringify(missing)}`});}
function assertUniqueActivity(state,label){const ids=state.activity.map((e)=>e.id);assert.equal(new Set(ids).size,ids.length,`${label}: duplicated activity ids ${JSON.stringify(ids)}`);}
async function relaunchClient(instance,label){await stopInstance(instance);await sleep(1500);return launchInstance(label,instance.dataRoot,await reservePort());}
async function stopInstance(instance){try{await instance.browser.deleteSession();}catch{}if(instance.child.pid&&instance.child.exitCode===null){spawnSync("taskkill.exe",["/PID",String(instance.child.pid),"/T","/F"],{stdio:"ignore",windowsHide:true});}}
async function clickIfPresent(browser,selector){const element=await browser.$(selector);if(!(await element.isExisting()))return false;if(!(await element.isDisplayed().catch(()=>false)))return false;await element.click();return true;}

async function runScenario(){
  assert.equal(process.platform,"win32","C1-MP Tauri acceptance is Windows-only");assert.ok(existsSync(binary),`Tauri E2E binary was not found: ${binary}`);
  await rm(runRoot,{recursive:true,force:true});await mkdir(artifactRoot,{recursive:true});await ensureVite();
  const sessionPort=await reservePort();const hostRoot=path.join(runRoot,"host","data");const p1Root=path.join(runRoot,"p1","data");const p2Root=path.join(runRoot,"p2","data");
  const host=await launchInstance("C1-MP Host",hostRoot,await reservePort());let p1=await launchInstance("C1-MP P1",p1Root,await reservePort());let p2=await launchInstance("C1-MP P2",p2Root,await reservePort());
  const peers=()=>[host,p1,p2];const scenarios={};const record=(id,data)=>{scenarios[id]={status:"PASS",...data};log(`${id} PASS`);};
  const CLERIC={className:"클레릭",spellTiles:{"choice:class.spells.cantrips":["신성한 불길","인도","빛"],"choice:class.spells.prepared":["신앙의 방패","상처 치료","유도 화살","치유의 단어"]},choiceCards:{"choice:class.divine-order":"수호자","choice:class.loadout.0":"부적"}};
  const cleric=await createDistinctPlayerCharacter(p1,"C1 Cleric",CLERIC);
  const shield=await stowShield(p1);log(`P1 shield: ${JSON.stringify(shield)}`);
  const fighter=await createDistinctPlayerCharacter(p2,"C1 Fighter");
  await createHostCampaign(host);await openHostSession(host,sessionPort);
  // C1-01 — the Host owns a saved character (the seeded Aelar) but hosting projects nothing of its own.
  const hosted=await stateOf(host);assert.equal(hosted.role,"host");assert.equal(hosted.entities.filter((e)=>e.kind==="character").length,0,`Host scene must start without characters; got ${JSON.stringify(hosted.entities)}`);
  await joinClientSession(p1,sessionPort);await joinClientSession(p2,sessionPort);
  const joined=await waitState(host,(s)=>s.entities.filter((e)=>e.kind==="character").length===2,"both players in the Host scene");
  const names=joined.entities.filter((e)=>e.kind==="character").map((e)=>e.name).sort();assert.deepEqual(names,["C1 Cleric","C1 Fighter"],`Host scene characters must be the two players only; got ${JSON.stringify(names)}`);
  assert.ok(!names.includes("Aelar"),"the DM's saved character must never enter the hosted scene");
  await evidenceAll(peers(),"c1-mp-01-joined");
  assert.equal(joined.activity.some((e)=>e.actor==="Aelar"||e.actor==="Mira"),false,`the reference fixture's 기록 entries must not appear in a hosted session; activity=${JSON.stringify(joined.activity.map((e)=>e.actor+": "+e.title))}`);
  const hostBody=await bodyText(host);const aelarAt=hostBody.indexOf("Aelar");assert.equal(aelarAt,-1,`the Host workspace must not name the DM's saved character; context=${JSON.stringify(hostBody.slice(Math.max(0,aelarAt-80),aelarAt+80))}`);
  record("C1-MP-01",{hostRole:hosted.role,characters:names,participants:joined.participants});
  try{
    // C1-MP-02 — an SRD monster added from the 인카운터 search reaches every peer with its catalog name and stat block.
    const bear=await addSrdMonsterViaUi(host,"흑곰","흑곰");assert.ok(bear,"흑곰 did not enter the Host scene");
    assert.equal(bear.maxHp,19,`흑곰 max HP from the stat block; got ${JSON.stringify(bear)}`);assert.equal(bear.ac,10,`흑곰 AC from the stat block; got ${JSON.stringify(bear)}`);
    await expectSceneParity(peers(),"C1-MP-02");
    await evidenceAll(peers(),"c1-mp-02-monster");
    record("C1-MP-02",{monster:bear});
    // C1-MP-04 — Initiative from the DM tools: order, round and current actor converge.
    const pane=await hostEncounterPane(host);await click(host.browser,`${pane}//button[normalize-space(.)='이니셔티브 시작']`,"이니셔티브 시작");
    const initiative=await waitState(host,(s)=>s.mode==="initiative"&&Boolean(s.currentActorId),"Initiative on the Host");
    await expectSceneParity(peers(),"C1-MP-04");
    await evidenceAll(peers(),"c1-mp-04-initiative");
    record("C1-MP-04",{round:initiative.round,currentActorId:initiative.currentActorId,order:initiative.entities.map((e)=>({name:e.name,initiative:e.initiative}))});
    // C1-MP-05 — P1 casts Guiding Bolt (spell attack, level-1 slot) at the bear: one Host resolution, HP and the slot converge.
    await walkToActor(host,cleric.id);
    // C1-MP-03 — on P1's turn, the dock's 물러남 declaration is routed to the Host and republished to the other player (the row renders in Initiative).
    let movementPath="ui";
    if(!(await clickIfPresent(p1.browser,exactButton("물러남")))){movementPath="api";await peerCall(p1,`await mockAdapter.declareMovement(args.actorId,"withdraw");`,{actorId:cleric.id});}
    const hostMove=await waitState(host,(s)=>s.entities.find((e)=>e.id===cleric.id)?.movement==="withdraw","the Host recording P1's 물러남");
    const p2Move=await waitState(p2,(s)=>s.entities.find((e)=>e.id===cleric.id)?.movement==="withdraw","P2 observing P1's 물러남");
    await evidenceAll(peers(),"c1-mp-03-movement");
    record("C1-MP-03",{path:movementPath,host:hostMove.entities.find((e)=>e.id===cleric.id).movement,p2:p2Move.entities.find((e)=>e.id===cleric.id).movement});
    const before05=await stateOf(p1);const slotBefore=before05.slots.find((l)=>l.level===1);assert.ok(slotBefore&&slotBefore.current>0,`P1 needs a level-1 slot; slots=${JSON.stringify(before05.slots)}`);
    const bolt=await findAction(p1,cleric.id,(a)=>a.spellId==="dnd.srd521.spell.guiding-bolt"&&a.available,"Guiding Bolt");
    await hostCall(host,`await mockAdapter.setQueuedD20(15);`);
    const cast=await clientAct(p1,bolt.id,[bear.id]);assert.equal(cast.ok,true,cast.error);
    let hostRes=await waitHostResolutionFor(host,cleric.id);const castDone=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(castDone.resolution?.stage,"complete",JSON.stringify(castDone.resolution));
    await expectConverged(peers(),castDone.resolution.id,"C1-MP-05");
    const after05=await waitState(p1,(s)=>s.slots.find((l)=>l.level===1)?.current===slotBefore.current-1,"one level-1 slot spent on P1");
    const bearAfterBolt=(await stateOf(host)).entities.find((e)=>e.id===bear.id);assert.ok(bearAfterBolt.hp<bear.maxHp,`Guiding Bolt with a queued 15 must hit AC 10; bear=${JSON.stringify(bearAfterBolt)}`);
    await expectSceneParity(peers(),"C1-MP-05");
    await evidenceAll(peers(),"c1-mp-05-spell");
    record("C1-MP-05",{resolutionId:castDone.resolution.id,slotBefore:slotBefore.current,slotAfter:after05.slots.find((l)=>l.level===1).current,bearHp:bearAfterBolt.hp});
    // C1-MP-06 — P2's weapon attack on the bear converges the same way.
    await walkToActor(host,fighter.id);
    const weapon=await findAction(p2,fighter.id,(a)=>a.available&&a.resolutionKind==="attack"&&(a.eligibleTargetIds??[]).includes(bear.id),"weapon attack");
    await hostCall(host,`await mockAdapter.setQueuedD20(15);`);
    const swing=await clientAct(p2,weapon.id,[bear.id]);assert.equal(swing.ok,true,swing.error);
    hostRes=await waitHostResolutionFor(host,fighter.id);const swingDone=await hostAdvanceToComplete(host,hostRes.resolution.id);assert.equal(swingDone.resolution?.stage,"complete",JSON.stringify(swingDone.resolution));
    await expectConverged(peers(),swingDone.resolution.id,"C1-MP-06");
    await expectSceneParity(peers(),"C1-MP-06");
    await evidenceAll(peers(),"c1-mp-06-attack");
    record("C1-MP-06",{resolutionId:swingDone.resolution.id,action:weapon.name,bearHp:(await stateOf(host)).entities.find((e)=>e.id===bear.id).hp});
    // C1-MP-07 — the DM resolves the bear's multiattack routine (찢기 2회) from the 인카운터 pane on the bear's turn; every attack reaches the players.
    await walkToActor(host,bear.id);
    const known=new Set((await stateOf(host)).activity.map((e)=>e.id));
    const pane07=await hostEncounterPane(host);
    await click(host.browser,`${pane07}//button[starts-with(normalize-space(.),'다중공격 · 찢기 2회')]`,"다중공격 · 찢기 2회");
    await click(host.browser,`${pane07}//div[@aria-label='흑곰 다중공격 대상']//button[normalize-space(.)='C1 Cleric']`,"다중공격 대상 C1 Cleric");
    const routineEntries=await newActivitySince(host,known,2);
    const routineIds=routineEntries.map((e)=>e.id);
    for(const p of [p1,p2])await waitActivityIds(p,routineIds);
    await expectSceneParity(peers(),"C1-MP-07");
    await evidenceAll(peers(),"c1-mp-07-multiattack");
    record("C1-MP-07",{entries:routineEntries.map((e)=>({actor:e.actor,title:e.title,summary:e.summary,stateChanges:e.stateChanges})),clericHp:(await stateOf(host)).entities.find((e)=>e.id===cleric.id).hp});
    // C1-MP-08 — P2's process is killed and relaunched on the same data; rejoining catches up to the Host scene and Activity exactly once.
    const hostBefore08=await stateOf(host);
    p2=await relaunchClient(p2,"C1-MP P2 Restart");
    await selectProductionCharacter(p2,fighter.id);await joinClientSession(p2,sessionPort);
    const caught=await waitState(p2,(s)=>JSON.stringify(publicEntities(s))===JSON.stringify(publicEntities(hostBefore08)),"catch-up scene parity after restart",40_000);
    await waitActivityIds(p2,[...routineIds,castDone.resolution.id,swingDone.resolution.id]);
    assertUniqueActivity(await stateOf(p2),"C1-MP-08");
    await expectSceneParity(peers(),"C1-MP-08");
    await evidenceAll(peers(),"c1-mp-08-rejoin");
    record("C1-MP-08",{mode:caught.mode,currentActorId:caught.currentActorId,activityCount:caught.activity.length});
    // C1-MP-09 — the Host ends the session explicitly; the players drop to offline without a silent reconnect.
    // The product shell stays live during a session (MP-A10): the 세션 screen carries the Host's 세션 종료.
    await click(host.browser,navButton("세션"),"Host 세션 메뉴");
    let ended=await clickIfPresent(host.browser,"//button[contains(@class,'danger-action') and normalize-space(.)='세션 종료']");
    if(!ended){await hostCall(host,`await mockAdapter.stopSession();`);}
    const hostEnded=await waitState(host,(s)=>s.role!=="host","the Host leaving the host role",30_000);
    const p1Ended=await waitState(p1,(s)=>s.role==="offline"||s.connectionState==="disconnected","P1 offline after the session end",40_000);
    const p2Ended=await waitState(p2,(s)=>s.role==="offline"||s.connectionState==="disconnected","P2 offline after the session end",40_000);
    await sleep(3000);
    const p1Still=await stateOf(p1);assert.notEqual(p1Still.connectionState,"connected","P1 must not silently reconnect after the Host ended the session");
    await evidenceAll(peers(),"c1-mp-09-ended");
    record("C1-MP-09",{viaUi:ended,host:{role:hostEnded.role,connectionState:hostEnded.connectionState},p1:{role:p1Ended.role,connectionState:p1Ended.connectionState},p2:{role:p2Ended.role,connectionState:p2Ended.connectionState}});
  }catch(error){await evidenceAll(peers(),"c1-mp-failure");const diag={};for(const p of peers())diag[p.label]=await bounded(stateOf(p).catch((e)=>({error:String(e)})),8_000,"state");await writeFile(path.join(artifactRoot,"c1-mp-failure-state.json"),`${JSON.stringify({scenarios,diag},null,2)}\n`,"utf8");throw error;}
  const evidence={gate:"C1-MP",scope:Object.keys(scenarios),status:"PASS",verificationSha,windowsTauri:true,topology:{host:"DM Host (no character)",clients:["P1 C1 Cleric","P2 C1 Fighter"],sessionPort},scenarios};
  await writeFile(path.join(artifactRoot,"c1-mp-summary.json"),`${JSON.stringify(evidence,null,2)}\n`,"utf8");log(`PASS evidence: ${path.join(artifactRoot,'c1-mp-summary.json')}`);
}

async function cleanup(){if(keepOpen){log(`--keep-open active. Evidence: ${artifactRoot}`);return;}for(const browser of [...browsers].reverse()){try{await browser.deleteSession();}catch{}}for(const child of [...children].reverse()){if(child.exitCode===null&&!child.killed){try{child.kill();}catch{}}}if(viteStarted)log("Vite process stopped with tracked child cleanup.");}

let exitCode=0;try{await runScenario();}catch(error){exitCode=1;console.error(error instanceof Error?error.stack??error.message:error);try{await writeFile(path.join(artifactRoot,"c1-mp-failure.txt"),`${String(error instanceof Error?error.stack??error.message:error)}\n`,"utf8");}catch{}}finally{await cleanup();}process.exitCode=exitCode;
